282	// ---------- Hover to inspect links ----------
283	// Emails hide the real address behind friendly text, the way real phishing
284	// does. Hovering (or tapping) shows where the link really goes. The link is a
285	// plain button, so it can never open anything.
286	const LINK_LABELS = [
287	  [/\.exe|download|update/i, "Download the update"],
288	  [/claim|winner|prize|reward/i, "Claim your reward"],
289	  [/sign-?in|log-?in/i, "Sign in to your account"],
290	  [/verify/i, "Verify your account"],
291	  [/confirm/i, "Confirm now"],
292	  [/billing|invoice|payment/i, "View billing details"],
293	  [/video|watch/i, "Watch now"],
294	  [/story|news|article/i, "Read the full story"],
295	];
