297	function parseLink(raw) {
298	  const text = String(raw || "").trim();
299	  try {
300	    const u = new URL(/^[a-z]+:\/\//i.test(text) ? text : `http://${text}`);
301	    const host = u.hostname;
302	    const parts = host.split(".");
303	    const domain = parts.length > 2 ? parts.slice(-2).join(".") : host;
304	    return {
305	      scheme: `${u.protocol}//`,
306	      sub: host.slice(0, host.length - domain.length), // e.g. "newsnow.com."
307	      domain,                                          // the site you really land on
308	      rest: u.pathname === "/" && !u.search ? "" : u.pathname + u.search,
309	    };
310	  } catch (e) {
311	    return { scheme: "", sub: "", domain: text, rest: "" };
312	  }
313	}
314	
315	function linkLabel(s) {
316	  if (s.link_text) return s.link_text;
317	  const { rest } = parseLink(s.link);
318	  const hit = LINK_LABELS.find(([re]) => re.test(rest)) || LINK_LABELS.find(([re]) => re.test(s.link));
319	  return hit ? hit[1] : "Open link";
320	}
