325	  if (s.channel === "sms") {
326	    // Texts show the raw address, but tapping it still previews the real site.
327	    return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">${esc(s.link)}</button>${hint}</p>`;
328	  }
329	  return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">🔗 ${esc(linkLabel(s))}</button>${hint}</p>`;
