362	// Always open ABOVE the link, so it never covers the Phish / Legit buttons
363	// below the message (one column). On wide screens the buttons sit to the
364	// right of the message, so the popup also stays inside the message column.
365	// If the link is too close to the top of the screen, scroll up to make room.
366	function placePeek() {
367	  if (!peekFor || peek.hidden) return;
368	  if (!document.body.contains(peekFor)) return hidePeek();
369	  const gap = 8, edge = 12;
370	  // Stay inside the message the link is in
371	  const column = (peekFor.closest(".email, .sms") || $("message")).getBoundingClientRect();
372	  peek.style.maxWidth = `${Math.max(200, Math.min(360, column.width, window.innerWidth - 2 * edge))}px`;
373	  const w = peek.offsetWidth, h = peek.offsetHeight;
374	  let r = peekFor.getBoundingClientRect();
375	  const short = edge - (r.top - gap - h);
376	  if (short > 0 && window.scrollY > 0) {
377	    window.scrollBy(0, -Math.min(short, window.scrollY));
378	    r = peekFor.getBoundingClientRect();
379	  }
380	  const right = Math.min(window.innerWidth - edge, column.right);
381	  const top = Math.max(edge, r.top - gap - h);
382	  const left = Math.min(Math.max(edge, r.left), right - w);
383	  peek.style.top = `${top}px`;
384	  peek.style.left = `${Math.max(edge, left)}px`;
385	}
