557	// ---------- Placing a callout ----------
558	// 1. Bring the target on screen.
559	// 2. Look for open space next to it (below, above, right, left, sliding along
560	//    each side) that stays on screen and covers no text, button, or the target.
561	// 3. No room? Scroll to make room above or below the target, and look again.
562	// 4. Still no room (for example inside the email on a phone)? Put the callout
563	//    in the page flow right under the target, so it pushes the content below
564	//    it down instead of covering it.
565	const TUT_GAP = 14;   // target to callout (leaves room for the arrow)
566	const TUT_EDGE = 8;   // callout to screen edge
567	const TUT_PAD = 4;    // breathing room around anything the callout must not cover
568	
569	// Paragraph-like elements: only their lines of text count, not empty padding.
570	const TEXT_SEL = "h1, h2, h3, p, li, th, td, .brand-name, .email-time, .link-hint, .streak";
571	// Solid things: their whole box counts.
572	const BOX_SEL = "button, input, img, .avatar, .dot, .answer, .status-bar";
573	const textRange = document.createRange();
