575	function tutorialObstacles(targetRect) {
576	  const rects = [];
577	  const add = (r) => { if (r.width >= 1 && r.height >= 1) rects.push(r); };
578	  const skip = (el) => tut.contains(el) || el.closest(".ocean-bg");
579	  document.querySelectorAll(TEXT_SEL).forEach((el) => {
580	    if (skip(el)) return;
581	    textRange.selectNodeContents(el);
582	    for (const r of textRange.getClientRects()) add(r);
583	  });
584	  document.querySelectorAll(BOX_SEL).forEach((el) => { if (!skip(el)) add(el.getBoundingClientRect()); });
585	  // The email's "INBOX" bar is drawn by CSS (::before), so add its label by hand
586	  document.querySelectorAll(".email").forEach((el) => {
587	    const r = el.getBoundingClientRect();
588	    if (r.height) add(new DOMRect(r.left + 12, r.top + 4, 70, 28));
589	  });
590	  // Never cover the target or its ring
591	  const t = targetRect;
592	  rects.push(new DOMRect(t.left - 6, t.top - 6, t.width + 12, t.height + 12));
593	  return rects;
594	}
